import React, { useState } from 'react';
import './App.css';

function App() {
  const [menu, setMenu] = useState({
    'Petit Déjeuner': [
      { name: 'Croissant', price: 1.5, selected: false },
      { name: 'Café', price: 2.0, selected: false },
      { name: 'Tartine Beurre', price: 1.2, selected: false },
    ],
    'Chicha': [
      { name: 'Double Pomme', price: 10, selected: false },
      { name: 'Menthe', price: 10, selected: false },
      { name: 'Raisin', price: 10, selected: false },
    ],
  });

  const toggleItem = (category, index) => {
    const updated = [...menu[category]];
    updated[index].selected = !updated[index].selected;
    setMenu({ ...menu, [category]: updated });
  };

  const accept = () => {
    let selectedItems = [];
    Object.entries(menu).forEach(([cat, items]) =>
      items.forEach(item => {
        if (item.selected) selectedItems.push(`${item.name} (${cat})`);
      })
    );
    alert("Vous avez choisi :\n" + selectedItems.join(', '));
  };

  const callWaiter = () => alert("Le serveur arrive !");

  return (
    <div className="container">
      <h1>🍽️ Menu du Café</h1>
      <div className="menu-columns">
        {Object.entries(menu).map(([category, items]) => (
          <div key={category} className="category">
            <h2>{category}</h2>
            {items.map((item, idx) => (
              <label key={idx} className="item">
                <input
                  type="checkbox"
                  checked={item.selected}
                  onChange={() => toggleItem(category, idx)}
                />
                {item.name} — {item.price} €
              </label>
            ))}
          </div>
        ))}
      </div>
      <div className="buttons">
        <button onClick={accept}>✅ Accepter</button>
        <button onClick={callWaiter}>🔔 Appeler le serveur</button>
      </div>
    </div>
  );
}

export default App;
